const ScreenProcessing = ({ onComplete, setBrandCore }) => {
  const [statusIndex, setStatusIndex] = useState(0);
  const statuses = [
    "Extracting core themes from Founder_Interview_Q3.pdf...",
    "Analyzing competitor positioning on stripe.com...",
    "Formulating Brand Archetype...",
    "Structuring Core Pillars..."
  ];

  useEffect(() => {
    const interval = setInterval(() => {
      setStatusIndex(prev => Math.min(prev + 1, statuses.length - 1));
    }, 2000);

    // Fire real AI call
    api.synthesizeBrand(SEED_INPUTS).then(result => {
      if (result && result.archetype) {
        setBrandCore(result);
      } else {
        // Fallback to seed if API fails or returns bad shape
        setBrandCore(SEED_BRAND_CORE);
      }
      setTimeout(() => onComplete(), 1000); // Give a moment to read final status
    });

    return () => clearInterval(interval);
  }, []);

  return (
    <motion.div 
      initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
      style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', height: 'calc(100vh - 80px)' }}
    >
      <motion.div
        animate={{ rotate: 360 }}
        transition={{ repeat: Infinity, duration: 3, ease: "linear" }}
        style={{ width: '64px', height: '64px', marginBottom: '32px' }}
      >
        <svg viewBox="0 0 50 50">
          <motion.circle
            cx="25" cy="25" r="20" fill="none" strokeWidth="4"
            strokeLinecap="round"
            initial={{ pathLength: 0.2, stroke: 'var(--text-secondary)' }}
            animate={{ 
              pathLength: [0.2, 0.8, 0.2],
              stroke: ['var(--text-secondary)', 'var(--nu-red)', 'var(--text-secondary)']
            }}
            transition={{ repeat: Infinity, duration: 2, ease: "easeInOut" }}
          />
        </svg>
      </motion.div>
      <AnimatePresence mode="wait">
        <motion.p
          key={statusIndex}
          initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }}
          style={{ fontFamily: 'var(--font-mono)', fontSize: '14px', color: 'var(--text-secondary)' }}
        >
          {statuses[statusIndex]}
        </motion.p>
      </AnimatePresence>
    </motion.div>
  );
};

