const ScreenVoiceTuner = ({ brandCore, voiceGuidelines, setVoiceGuidelines, toneValue, setToneValue }) => {
  const [isTuning, setIsTuning] = useState(false);

  const handleSliderRelease = async () => {
    setIsTuning(true);
    const newGuidelines = await api.tuneVoice(brandCore, toneValue);
    if (newGuidelines && newGuidelines.length > 0) {
      setVoiceGuidelines(newGuidelines);
    }
    setIsTuning(false);
  };

  return (
    <motion.div 
      initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }}
      style={{ maxWidth: '1000px', margin: '64px auto', padding: '0 32px', display: 'grid', gridTemplateColumns: '300px 1fr', gap: '64px' }}
    >
      {/* Sidebar Controls */}
      <div>
        <h2 style={{ fontFamily: 'var(--font-display)', fontSize: '32px', fontWeight: 700, marginBottom: '32px' }}>Voice Tuner</h2>

        <div style={{ marginBottom: '48px' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '12px' }}>
            <span style={{ fontFamily: 'var(--font-label)', fontSize: '14px' }}>Tone</span>
            <span style={{ fontFamily: 'var(--font-mono)', fontSize: '12px', color: 'var(--text-secondary)' }}>{toneValue}</span>
          </div>
          <input 
            type="range" min="0" max="100" value={toneValue}
            onChange={(e) => setToneValue(parseInt(e.target.value))}
            onMouseUp={handleSliderRelease}
            onTouchEnd={handleSliderRelease}
            style={{ width: '100%', cursor: 'pointer', accentColor: 'var(--nu-red)' }}
          />
          <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '8px', fontFamily: 'var(--font-body)', fontSize: '12px', color: 'var(--text-secondary)' }}>
            <span>Authoritative</span>
            <span>Playful</span>
          </div>
        </div>

        <div style={{ padding: '24px', backgroundColor: 'var(--surface)', borderRadius: 'var(--card-radius)' }}>
          <lucide.Info size={16} color="var(--text-secondary)" style={{ marginBottom: '12px' }} />
          <p style={{ fontFamily: 'var(--font-body)', fontSize: '14px', color: 'var(--text-secondary)', lineHeight: 1.5 }}>
            Adjusting the slider recalculates the brand's voice guidelines in real-time using Gemini 3.1 Pro.
          </p>
        </div>
      </div>

      {/* Live Preview Panel */}
      <div>
        <h3 style={{ fontFamily: 'var(--font-label)', fontSize: '18px', marginBottom: '24px', borderBottom: '1px solid var(--border)', paddingBottom: '8px' }}>
          Live Guidelines
        </h3>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '24px', position: 'relative' }}>
          {isTuning && (
            <motion.div 
              initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
              style={{ position: 'absolute', inset: 0, backgroundColor: 'rgba(255,255,255,0.8)', zIndex: 2, display: 'flex', alignItems: 'center', justifyContent: 'center' }}
            >
              <span style={{ fontFamily: 'var(--font-mono)', fontSize: '14px', color: 'var(--nu-red)' }}>Recalculating voice...</span>
            </motion.div>
          )}

          {voiceGuidelines.map((guide, idx) => (
            <div key={idx} style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' }}>
              <div style={{ padding: '16px', borderLeft: '4px solid var(--success)', backgroundColor: 'var(--surface)', borderRadius: '0 var(--radius) var(--radius) 0' }}>
                <span style={{ fontFamily: 'var(--font-label)', fontSize: '12px', color: 'var(--success)', display: 'block', marginBottom: '8px', textTransform: 'uppercase' }}>Do Say</span>
                <p style={{ fontFamily: 'var(--font-body)', fontSize: '16px', color: 'var(--text-primary)' }}>"{guide.do}"</p>
              </div>
              <div style={{ padding: '16px', borderLeft: '4px solid var(--friction)', backgroundColor: 'var(--surface)', borderRadius: '0 var(--radius) var(--radius) 0' }}>
                <span style={{ fontFamily: 'var(--font-label)', fontSize: '12px', color: 'var(--friction)', display: 'block', marginBottom: '8px', textTransform: 'uppercase' }}>Don't Say</span>
                <p style={{ fontFamily: 'var(--font-body)', fontSize: '16px', color: 'var(--text-secondary)', textDecoration: 'line-through' }}>"{guide.dont}"</p>
              </div>
            </div>
          ))}
        </div>
      </div>
    </motion.div>
  );
};

const OracleResultCard = ({ res, idx }) => {
  const [copied, setCopied] = useState(false);
  const [isHovered, setIsHovered] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(res.text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <motion.div 
