            maxHeight: '80vh'
          }}
        >
          <form onSubmit={handleSubmit} style={{ padding: '24px', borderBottom: '1px solid var(--border)', display: 'flex', alignItems: 'center', gap: '16px' }}>
            <lucide.Sparkles color="var(--nu-red)" />
            <input 
              ref={inputRef}
              value={prompt}
              onChange={e => setPrompt(e.target.value)}
              placeholder="Ask the Brand Oracle (e.g., 'Write a hero headline for our new API')"
              style={{
                flex: 1, border: 'none', outline: 'none', fontFamily: 'var(--font-body)', fontSize: '18px',
                backgroundColor: 'transparent', color: 'var(--text-primary)'
              }}
            />
            <kbd style={{ fontFamily: 'var(--font-mono)', fontSize: '12px', color: 'var(--text-secondary)' }}>↵</kbd>
          </form>

          <div style={{ padding: '24px', overflowY: 'auto', flex: 1, backgroundColor: 'var(--surface)' }}>
            {isGenerating && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
                {[1,2,3].map(i => (
                  <div key={i} style={{ height: '80px', backgroundColor: 'var(--border)', borderRadius: 'var(--card-radius)', opacity: 0.5, animation: 'pulse 1.5s infinite' }} />
                ))}
              </div>
            )}

            {!isGenerating && results.length === 0 && (
              <div style={{ textAlign: 'center', color: 'var(--text-secondary)', padding: '48px 0' }}>
                <p style={{ fontFamily: 'var(--font-body)', fontSize: '14px' }}>The Oracle is listening. Press Enter to generate.</p>
              </div>
            )}

            {!isGenerating && results.length > 0 && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
                {results.map((res, idx) => (
                  <OracleResultCard key={idx} res={res} idx={idx} />
                ))}
              </div>
            )}
          </div>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
};

// --- Main App ---

const App = () => {
  const [currentScreen, setCurrentScreen] = useState('screen_01_ingestion_canvas');
  const [brandCore, setBrandCore] = useState(SEED_BRAND_CORE);
  const [voiceGuidelines, setVoiceGuidelines] = useState(SEED_VOICE);
  const [toneValue, setToneValue] = useState(50);
  const [isOracleOpen, setIsOracleOpen] = useState(false);

  // Inject CSS Variables
  useEffect(() => {
    const style = document.createElement('style');
    style.innerHTML = `
      @import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Mono&family=Open+Sans:wght@400;600;700&family=Roboto+Condensed:wght@400;700&display=swap');
      :root {
        --bg: #FFFFFF;
        --surface: #F7F7F7;
        --text-primary: #000000;
        --text-secondary: #414141;
        --border: #D9D9D9;
        --nu-red: #C8102E;
        --cream: #F8E5C2;
        --success: #0F8A4B;
        --warning: #B5651D;
        --friction: #9E0A24;

        --font-display: 'Roboto Condensed', sans-serif;
        --font-body: 'Open Sans', sans-serif;
        --font-label: 'Open Sans', sans-serif;
