      @keyframes pulse { 0% { opacity: 0.3; } 50% { opacity: 0.7; } 100% { opacity: 0.3; } }
    `;
    document.head.appendChild(style);
    return () => document.head.removeChild(style);
  }, []);

  // Global Cmd+K Listener
  useEffect(() => {
    const handleKeyDown = (e) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        // Only allow Oracle if we have a brand core synthesized
        if (currentScreen !== 'screen_01_ingestion_canvas' && currentScreen !== 'screen_02_synthesis_processing') {
          setIsOracleOpen(prev => !prev);
        }
      }
      if (e.key === 'Escape') {
        setIsOracleOpen(false);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [currentScreen]);

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>
      <Header currentScreen={currentScreen} setScreen={setCurrentScreen} />

      <main style={{ flex: 1, position: 'relative' }}>
        <AnimatePresence mode="wait">
          {currentScreen === 'screen_01_ingestion_canvas' && (
            <ScreenIngestion key="s1" onSynthesize={() => setCurrentScreen('screen_02_synthesis_processing')} />
          )}
          {currentScreen === 'screen_02_synthesis_processing' && (
            <ScreenProcessing key="s2" setBrandCore={setBrandCore} onComplete={() => setCurrentScreen('screen_03_brand_core')} />
          )}
          {currentScreen === 'screen_03_brand_core' && (
            <ScreenBrandCore key="s3" brandCore={brandCore} />
          )}
          {currentScreen === 'screen_04_voice_tuner' && (
            <ScreenVoiceTuner key="s4" brandCore={brandCore} voiceGuidelines={voiceGuidelines} setVoiceGuidelines={setVoiceGuidelines} toneValue={toneValue} setToneValue={setToneValue} />
          )}
        </AnimatePresence>
      </main>

      <OracleModal 
        isOpen={isOracleOpen} 
        onClose={() => setIsOracleOpen(false)} 
        brandCore={brandCore}
        toneValue={toneValue}
      />

      <DemoControls setScreen={setCurrentScreen} />
    </div>
  );
};

